// Guided-tour engine (generic). Configure once with your steps; optionally a voice timeline.
//
//   configureTour({ steps, voice })
//   steps: [{ id, route, target, title, body, say?, action?: () => void }]
//     - target = value of a data-tour="..." attribute to spotlight
//     - action runs when the cue word is spoken (voice) or as the step starts (no voice)
//   voice (optional, generated by tour_voice.py): { lead, total, steps: { [id]: { file, slot, cueAt } } }
//
// With voice: each step owns a fixed slot (clip length), so the tour always runs the same length.
// Without voice: browser speech synthesis (if available) and ~46 ms per caption character.
import { useSyncExternalStore } from "react";
import { navigate } from "../lib/router";
import { speak, stopSpeaking, canSpeak } from "../lib/speech";

let STEPS = [];
let VOICE = { steps: {} };
const VOICE_KEY = "tour-voice";
const voicePref = () => { try { return localStorage.getItem(VOICE_KEY) !== "off"; } catch { return true; } };

let st = { active: false, index: 0, playing: true, narrate: voicePref(), stepStarted: 0, duration: 0, target: null };
const subs = new Set();
const set = (patch) => { st = { ...st, ...patch }; subs.forEach((f) => f()); };
export const useTour = () => useSyncExternalStore((f) => { subs.add(f); return () => subs.delete(f); }, () => st);
export const getSteps = () => STEPS;

export function configureTour({ steps, voice }) { STEPS = steps || []; VOICE = voice || { steps: {} }; }

const clips = {};
let audio = null;
let timers = [];
let token = 0;
const clear = () => { timers.forEach(clearTimeout); timers = []; };
const later = (fn, ms) => timers.push(setTimeout(fn, ms));
const stopAudio = () => { if (audio) { audio.pause(); audio = null; } stopSpeaking(); };
const clipOf = (id) => {
  const v = VOICE.steps?.[id];
  if (!v) return null;
  if (!clips[id]) { clips[id] = new Audio(v.file); clips[id].preload = "auto"; }
  return clips[id];
};
const waitFor = (sel, ms) => new Promise((resolve) => {
  const t0 = Date.now();
  const tick = () => {
    const el = sel && document.querySelector(`[data-tour="${sel}"]`);
    if (el || Date.now() - t0 > ms) return resolve(el || null);
    setTimeout(tick, 40);
  };
  tick();
});

async function run(i) {
  clear(); stopAudio();
  const my = ++token;
  const step = STEPS[i];
  if (!step) return stop();
  const v = VOICE.steps?.[step.id];
  const slotMs = v ? v.slot * 1000 : Math.max(4200, (step.say || step.body).length * 46);
  const t0 = performance.now();
  set({ index: i, stepStarted: Date.now(), duration: slotMs, target: null });
  if (step.route) navigate(step.route);
  later(() => { if (my === token && st.active && st.playing) run(i + 1); }, slotMs);
  const el = await waitFor(step.target, 1500);
  if (my !== token) return;
  el?.scrollIntoView({ behavior: "smooth", block: "center" });
  set({ target: step.target });
  later(() => {
    if (my !== token) return;
    const clip = clipOf(step.id);
    if (clip) {
      audio = clip; clip.currentTime = 0; clip.muted = !st.narrate;
      clip.play().catch(() => {});
    } else if (st.narrate && canSpeak()) speak(step.say || step.body, { rate: 1.05 });
    if (step.action) later(() => { if (my === token) Promise.resolve(step.action()).catch((e) => console.warn("tour action", e)); }, (v?.cueAt || 0) * 1000);
  }, Math.max(0, (VOICE.lead ?? 0.35) * 1000 - (performance.now() - t0)));
}

export function setBuiltInVoice(on) {
  try { localStorage.setItem(VOICE_KEY, on ? "on" : "off"); } catch { /* session only */ }
  if (audio) audio.muted = !on;
  set({ narrate: on });
}
export function start(from = 0) {
  STEPS.forEach((s) => clipOf(s.id));
  set({ active: true, playing: true, narrate: voicePref() });
  const first = clipOf(STEPS[from]?.id);
  if (first && first.readyState < 3) {
    let go = false;
    const begin = () => { if (!go) { go = true; run(from); } };
    first.addEventListener("canplaythrough", begin, { once: true });
    setTimeout(begin, 1500);
  } else run(from);
}
export function stop() { token++; clear(); stopAudio(); set({ active: false, target: null }); }
export function next() { run(Math.min(STEPS.length - 1, st.index + 1)); }
export function prev() { run(Math.max(0, st.index - 1)); }
export function togglePlay() {
  if (st.playing) { token++; clear(); stopAudio(); set({ playing: false }); } else { set({ playing: true }); run(st.index); }
}
export function toggleNarrate() { const n = !st.narrate; if (audio) audio.muted = !n; if (!n) stopSpeaking(); set({ narrate: n }); }
